{"results": [{"id": "hp_doc_6c0b65ad21dccbdee3c34059be60acf60ec19956c7c490ff77f3f48a4e7cfae1", "title": "Michigan gubernatorial election, 2006", "text": "The Michigan gubernatorial election of 2006 was one of the 36 U.S. gubernatorial elections held November 7, 2006. Incumbent Democratic Governor Jennifer Granholm was re-elected over Republican businessman Dick DeVos and three minor party candidates. Granholm was re-elected with 56% of the vote.", "score": 30.9276}, {"id": "hp_doc_72791e96963b46959e0990f621ce40bdaa7cc1cbdd7a2c71b0917a0315392dfe", "title": "Michigan gubernatorial election, 1954", "text": "The 1954 Michigan gubernatorial election took place on November 2, 1954, to elect the governor of Michigan.", "score": 27.931}, {"id": "hp_doc_a570ded970ce423605f907148a25a504127b935350890027ed58ec45adf67d34", "title": "Michigan gubernatorial election, 2014", "text": "The Michigan gubernatorial election of 2014 took place on November 4, 2014, to elect the Governor of Michigan, concurrently with the election of Michigan's Class II U.S. Senate seat, as well as other elections to the United States Senate in other states and elections to the United States House of Representatives and various state and local elections.", "score": 24.8657}], "remaining_searches": 2}
